import "server-only";
import { claim, markFailed, markSent } from "@/lib/outbox";
import { deliver } from "./messages";

export type DrainResult = { claimed: number; sent: number; skipped: number; failed: number };

/**
 * Processes one batch. Safe to run concurrently on any number of instances —
 * `claim` hands each row to exactly one worker (FOR UPDATE SKIP LOCKED).
 */
export async function drainOnce(batchSize = 20): Promise<DrainResult> {
  const messages = await claim(batchSize);
  const result: DrainResult = { claimed: messages.length, sent: 0, skipped: 0, failed: 0 };

  for (const msg of messages) {
    try {
      const outcome = await deliver(msg);
      await markSent(msg.id);
      if (outcome === "sent") result.sent++;
      else result.skipped++;
    } catch (error) {
      await markFailed(msg, error);
      result.failed++;
    }
  }
  return result;
}

/** Long-running loop for `pnpm worker`. */
export async function runWorker(intervalMs = 2000): Promise<never> {
  for (;;) {
    try {
      const r = await drainOnce();
      if (r.claimed > 0) {
        console.log(
          JSON.stringify({ at: new Date().toISOString(), component: "outbox-worker", ...r }),
        );
      }
    } catch (error) {
      console.error(
        JSON.stringify({
          at: new Date().toISOString(),
          component: "outbox-worker",
          error: error instanceof Error ? error.message : String(error),
        }),
      );
    }
    await new Promise((r) => setTimeout(r, intervalMs));
  }
}
import "server-only";
import { and, eq, sql } from "drizzle-orm";
import { db, schema as s } from "@/db";
import type { Tx } from "@/db";

export type OutboxMessage = {
  businessId: string;
  topic: string;
  payload: Record<string, unknown>;
  /** Natural key; a second enqueue with the same key is a no-op. */
  dedupeKey?: string;
  /** Delay delivery until this instant (reminders, offers with a deadline). */
  availableAt?: Date;
  maxAttempts?: number;
};

/**
 * Enqueue inside the caller's transaction. Never call this with the global
 * `db` when a business row is being written — that is the whole point of the
 * pattern: message and change commit together or not at all.
 */
export async function enqueue(tx: Tx, msg: OutboxMessage): Promise<void> {
  await tx
    .insert(s.outbox)
    .values({
      businessId: msg.businessId,
      topic: msg.topic,
      payload: msg.payload,
      dedupeKey: msg.dedupeKey ?? null,
      availableAt: msg.availableAt ?? new Date(),
      maxAttempts: msg.maxAttempts ?? 5,
    })
    .onConflictDoNothing({ target: s.outbox.dedupeKey });
}

/** Drop a scheduled message that is no longer wanted (booking cancelled…). */
export async function cancelByDedupeKey(tx: Tx, dedupeKey: string): Promise<void> {
  await tx
    .update(s.outbox)
    .set({ status: "cancelled", updatedAt: new Date() })
    .where(and(eq(s.outbox.dedupeKey, dedupeKey), eq(s.outbox.status, "pending")));
}

export type ClaimedMessage = typeof s.outbox.$inferSelect;

/** How long a claimed message stays reserved before another worker may retry it. */
export const LEASE_SEC = 60;

/** Raw SQL returns snake_case columns; drizzle's select does not. Bridge them. */
type OutboxRow = {
  id: string;
  business_id: string;
  topic: string;
  payload: unknown;
  dedupe_key: string | null;
  available_at: Date;
  status: (typeof s.outboxStatuses)[number];
  attempts: number;
  max_attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
};

const toMessage = (r: OutboxRow): ClaimedMessage => ({
  id: r.id,
  businessId: r.business_id,
  topic: r.topic,
  payload: r.payload,
  dedupeKey: r.dedupe_key,
  availableAt: r.available_at,
  status: r.status,
  attempts: r.attempts,
  maxAttempts: r.max_attempts,
  lastError: r.last_error,
  createdAt: r.created_at,
  updatedAt: r.updated_at,
});

/**
 * Atomically claim up to `limit` due messages.
 *
 * Two mechanisms, doing different jobs:
 *  - FOR UPDATE SKIP LOCKED keeps simultaneous claimers off each other's rows
 *    inside the statement — a locked row is invisible rather than blocking.
 *  - Flipping the row to 'processing' with `available_at` pushed out by
 *    LEASE_SEC keeps it claimed *after* the statement commits. Row locks end
 *    with the statement; without the lease a second worker a millisecond later
 *    would happily claim the same message again.
 *
 * The lease doubles as crash recovery: a worker that dies mid-delivery leaves
 * the row reserved only until the lease lapses, then it is retried.
 */
export async function claim(limit: number): Promise<ClaimedMessage[]> {
  const { rows } = await db.execute<OutboxRow>(sql`
    WITH due AS (
      SELECT id FROM outbox
      WHERE status IN ('pending', 'processing') AND available_at <= now()
      ORDER BY available_at
      FOR UPDATE SKIP LOCKED
      LIMIT ${limit}
    )
    UPDATE outbox o
    SET attempts    = o.attempts + 1,
        status      = 'processing',
        available_at = now() + (${LEASE_SEC} || ' seconds')::interval,
        updated_at  = now()
    FROM due
    WHERE o.id = due.id
    RETURNING o.*
  `);
  return rows.map(toMessage);
}

export async function markSent(id: string): Promise<void> {
  await db
    .update(s.outbox)
    .set({ status: "sent", updatedAt: new Date(), lastError: null })
    .where(eq(s.outbox.id, id));
}

/** Exponential backoff: 2s, 4s, 8s, 16s… then give up and mark it dead. */
export async function markFailed(msg: ClaimedMessage, error: unknown): Promise<void> {
  const message = error instanceof Error ? error.message : String(error);
  const exhausted = msg.attempts >= msg.maxAttempts;
  await db
    .update(s.outbox)
    .set({
      status: exhausted ? "dead" : "pending",
      lastError: message.slice(0, 1000),
      availableAt: new Date(Date.now() + 2 ** msg.attempts * 1000),
      updatedAt: new Date(),
    })
    .where(eq(s.outbox.id, msg.id));
}
import { eq } from "drizzle-orm";
import { afterAll, beforeEach, describe, expect, it } from "vitest";
import { db, schema as s } from "@/db";
import { createBooking, createHold, getAvailability, setBookingStatus } from "@/lib/booking";
import { drainOnce } from "@/lib/notify/worker";
import { redis } from "@/lib/redis";
import { atLocal, futureDateISO, resetAll, seedBusiness, type Fixture } from "@/test/fixtures";
import { acceptOffer, expireOffer, joinWaitlist } from "./waitlist";

let f: Fixture;
const date = futureDateISO();
const HH = "12:00";

beforeEach(async () => {
  await resetAll();
  f = await seedBusiness();
});

afterAll(async () => {
  await redis().quit();
});

function slotAt(hhmm = HH) {
  const start = atLocal(date, hhmm, f.business.timezone);
  return { startMs: start, endMs: start + 3600_000 };
}

async function book(phone = "+77010000001", hhmm = HH) {
  const slot = slotAt(hhmm);
  const token = (await createHold(f.master.id, slot, 300))!;
  return createBooking({
    businessId: f.business.id,
    staffId: f.master.id,
    serviceId: f.service.id,
    slot,
    holdToken: token,
    client: { name: "Booked", phone },
  });
}

const join = (phone: string, staffId?: string | null) =>
  joinWaitlist({
    businessId: f.business.id,
    serviceId: f.service.id,
    staffId,
    dateISO: date,
    client: { name: `W-${phone.slice(-4)}`, phone },
  });

async function cancel(bookingId: string) {
  await setBookingStatus({
    businessId: f.business.id,
    bookingId,
    status: "cancelled",
    actorUserId: f.owner.id,
  });
}

const entries = () => db.select().from(s.waitlistEntries);
const messages = () => db.select().from(s.messageLog);

describe("joining", () => {
  it("records the client and the requested day", async () => {
    await join("+77011111111");
    const [entry] = await entries();
    expect(entry.status).toBe("waiting");
    expect(entry.dateISO).toBe(date);

    const [client] = await db.select().from(s.clients);
    expect(client.phone).toBe("+77011111111");
  });

  it("reuses an existing client for the same phone", async () => {
    await join("+77011111111");
    await join("+77011111111");
    expect(await db.select().from(s.clients)).toHaveLength(1);
    expect(await entries()).toHaveLength(2);
  });
});

describe("offering a freed slot", () => {
  it("offers to the longest-waiting client and holds the slot for them", async () => {
    const booked = await book();
    await join("+77012222222"); // first in line
    await join("+77013333333");

    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce(); // slot_freed -> offer
    await drainOnce(); // deliver the offer SMS

    const rows = await entries();
    const offered = rows.filter((r) => r.status === "offered");
    expect(offered).toHaveLength(1);
    expect(offered[0].offerToken).toBeTruthy();

    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, offered[0].clientId));
    expect(client.phone).toBe("+77012222222");

    // Held for them: the public availability no longer shows the slot.
    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).not.toContain(slotAt().startMs);

    const sms = await messages();
    expect(sms.some((m) => m.recipient === "+77012222222" && m.subject.includes("a slot has opened up")))
      .toBe(true);
  });

  it("skips clients who wanted a different master", async () => {
    const [other] = await db
      .insert(s.staff)
      .values({ businessId: f.business.id, name: "Other" })
      .returning();

    const booked = await book();
    await join("+77014444444", other.id); // wants someone else
    await join("+77015555555", null); // any master

    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, offered.clientId));
    expect(client.phone).toBe("+77015555555");
  });

  it("does nothing when nobody is waiting", async () => {
    const booked = await book();
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    expect(await entries()).toHaveLength(0);

    // Slot returns to public stock.
    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
  });
});

describe("accepting an offer", () => {
  it("turns the offer into a booking", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    const result = await acceptOffer(offered.offerToken!);
    expect(result.ok).toBe(true);

    const confirmed = await db
      .select()
      .from(s.bookings)
      .where(eq(s.bookings.status, "confirmed"));
    expect(confirmed).toHaveLength(1);
    expect((await entries())[0].status).toBe("booked");
  });

  it("refuses an unknown or already-used token", async () => {
    expect(await acceptOffer("nope")).toEqual({ ok: false, error: "not_found" });
  });

  it("refuses once the deadline has passed", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    await db
      .update(s.waitlistEntries)
      .set({ offerExpiresAt: new Date(Date.now() - 1000) })
      .where(eq(s.waitlistEntries.id, offered.id));

    expect(await acceptOffer(offered.offerToken!)).toEqual({ ok: false, error: "expired" });
  });
});

describe("offer expiry moves down the queue", () => {
  it("passes the slot to the next person when the first does not answer", async () => {
    const booked = await book();
    await join("+77012222222"); // first
    await join("+77013333333"); // second

    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const first = (await entries()).find((r) => r.status === "offered")!;
    await expireOffer(first.id);
    await drainOnce(); // the re-announced slot_freed
    await drainOnce(); // deliver the second offer

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("expired");

    const second = rows.find((r) => r.status === "offered")!;
    const [client] = await db
      .select()
      .from(s.clients)
      .where(eq(s.clients.id, second.clientId));
    expect(client.phone).toBe("+77013333333");
  });

  it("returns the slot to public stock once the queue is exhausted", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const only = (await entries()).find((r) => r.status === "offered")!;
    await expireOffer(only.id);
    await drainOnce();

    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
  });

  it("leaves an already-accepted offer alone", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();

    const offered = (await entries()).find((r) => r.status === "offered")!;
    await acceptOffer(offered.offerToken!);
    await expireOffer(offered.id); // deadline fires after acceptance

    expect((await entries())[0].status).toBe("booked");
    expect(await db.select().from(s.bookings).where(eq(s.bookings.status, "confirmed")))
      .toHaveLength(1);
  });
});
