t=open(p).read()
t=t.replace('import { acceptOffer, expireOffer, joinWaitlist }','import { acceptOffer, declineOffer, expireOffer, joinWaitlist }')
t+='''
describe("declining an offer", () => {
  async function offerTo(...phones: string[]) {
    const booked = await book();
    for (const p of phones) await join(p);
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    return (await entries()).find((r) => r.status === "offered")!;
  }

  const phoneOf = async (clientId: string) =>
    (await db.select().from(s.clients).where(eq(s.clients.id, clientId)))[0].phone;

  it("kills the link and offers the slot to the next client once", async () => {
    const first = await offerTo("+77012222222", "+77013333333");
    const token = first.offerToken!;

    const results = await Promise.all([declineOffer(token), declineOffer(token), declineOffer(token)]);
    expect(results.filter((r) => r.ok)).toHaveLength(1);
    expect(await acceptOffer(token)).toEqual({ ok: false, error: "not_found" });

    await drainOnce();
    await drainOnce();

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("declined");
    const offered = rows.filter((r) => r.status === "offered");
    expect(offered).toHaveLength(1);
    expect(await phoneOf(offered[0].clientId)).toBe("+77013333333");
    const offerSms = (await messages()).filter((m) => m.subject.includes("a slot has opened up"));
    expect(offerSms.filter((m) => m.recipient === "+77013333333")).toHaveLength(1);
  });

  it("puts the slot back on the public page when nobody else waits", async () => {
    const only = await offerTo("+77012222222");
    expect((await declineOffer(only.offerToken!)).ok).toBe(true);

    const free = await getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });
    expect(free.map((sl) => sl.startMs)).toContain(slotAt().startMs);
    await drainOnce();
    expect((await entries()).filter((r) => r.status === "offered")).toHaveLength(0);
  });

  it("does nothing once the offer has been claimed", async () => {
    const first = await offerTo("+77012222222", "+77013333333");
    expect((await acceptOffer(first.offerToken!)).ok).toBe(true);
    expect((await declineOffer(first.offerToken!)).ok).toBe(false);
    await drainOnce();

    expect(await db.select().from(s.bookings).where(eq(s.bookings.status, "confirmed")))
      .toHaveLength(1);
    expect((await entries()).filter((r) => r.status === "offered")).toHaveLength(0);
  });
});
'''
